// ocr.siliconwat.dev's service worker — generated by scripts/build-sw.mjs from scripts/sw.template.js (never edit dist/sw.js).
// What it is for (the transcriber's use case, 2026-11-20): monks and scholars with patchy internet read on after one visit, and on
// Android a screenshot can be SHARED straight to the page. What it promises:
//  · the page itself always comes from the network when online (network-first); the stored copy is used only offline, so a
//    returning visitor is never stuck on an old build;
//  · every other file is named by its content (hashed) or never changes under its name, so it is served from storage once seen;
//  · ⛔ it never touches another site: the visit counter and the voice service pass straight through;
//  · a shared picture is held on this device only until the page takes it, then deleted. It is never uploaded.
const VERSION = "__VERSION__";
const SHELL = `shell-${VERSION}`, RUNTIME = "runtime-v1", INBOX = "share-inbox";
const PRECACHE = __PRECACHE__;

self.addEventListener("install", (e) => {
  e.waitUntil(caches.open(SHELL).then((c) => c.addAll(PRECACHE)).then(() => self.skipWaiting()));
});
self.addEventListener("activate", (e) => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith("shell-") && k !== SHELL) await caches.delete(k);
    await self.clients.claim();
  })());
});
self.addEventListener("fetch", (e) => {
  const req = e.request, url = new URL(req.url);
  if (url.origin !== location.origin) return;
  if (req.method === "POST" && url.pathname === "/share") { e.respondWith(receiveShare(req)); return; }
  if (req.method !== "GET") return;
  if (req.mode === "navigate") { e.respondWith(networkFirst(req, url)); return; }
  if (/^\/(vendor|models|dict)\//.test(url.pathname)) { e.respondWith(cacheFirst(req, RUNTIME)); return; }
  e.respondWith(cacheFirst(req, SHELL));
});
async function networkFirst(req, url) {
  try { return await fetch(req); }
  catch {
    const c = await caches.open(SHELL);
    return (await c.match(url.pathname.startsWith("/km") ? "/km/" : "/")) || Response.error();
  }
}
async function cacheFirst(req, name) {
  const c = await caches.open(name), hit = await c.match(req);
  if (hit) return hit;
  const r = await fetch(req);
  if (r.ok && r.type === "basic") c.put(req, r.clone());
  return r;
}
// Android's share sheet POSTs the picture here (site.webmanifest share_target). It waits in this device's storage until the page
// opens and takes it (src/share.ts), which deletes it.
async function receiveShare(req) {
  const form = await req.formData(), files = form.getAll("page").filter((f) => typeof f === "object" && f && "size" in f);
  const c = await caches.open(INBOX);
  for (const k of await c.keys()) await c.delete(k);
  let i = 0;
  for (const f of files) await c.put(`/__share/${i++}`, new Response(f, { headers: { "content-type": f.type || "application/octet-stream", "x-name": encodeURIComponent(f.name || `shared-${i}`) } }));
  return Response.redirect(`/?share=${files.length}`, 303);
}
